def main():
    if not (ROOT / "app" / "trace.py").exists() or not (ROOT / "app" / "api" / "v21.py").exists():
        print("Install the v2.1 kit first (python install_v21.py), then run this again.")
        return 2
    stamp = datetime.now().strftime("%Y%m%d-%H%M%S")
    changed = 0
    for rel, text in FILES.items():
        path = ROOT / rel
        if path.exists():
            if path.read_text(encoding="utf-8", errors="replace") == text:
                continue
            dest = ROOT / ".v21_backup" / stamp / rel
            dest.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(path, dest)
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(text, encoding="utf-8", newline="\n")
        changed += 1
    print("Live-scan upgrade: %d of %d files updated (backups in .v21_backup/%s/)" % (changed, len(FILES), stamp))
    bad = []
    for rel in FILES:
        if rel.endswith(".py"):
            try:
                py_compile.compile(str(ROOT / rel), doraise=True)
            except py_compile.PyCompileError as exc:
                bad.append(str(exc))
    print("  [OK]   Python files compile" if not bad else "  [FAIL] " + "\n".join(bad))
    try:
        sys.path.insert(0, str(ROOT))
        import app.api.v21  # noqa: F401
        import app.trace as t
        assert hasattr(t, "finding") and hasattr(t, "set_pace")
        print("  [OK]   app.api.v21 and app.trace import (live pace + findings available)")
    except Exception as exc:  # noqa: BLE001
        print("  [FAIL] import: %s: %s (is the venv active?)" % (type(exc).__name__, exc))
    pipe = (ROOT / "app" / "pipeline.py").read_text(encoding="utf-8") if (ROOT / "app" / "pipeline.py").exists() else ""
    n = pipe.count("trace.finding(") + pipe.count("trace.signal_findings(") + pipe.count("trace.progress(")
    print(("  [OK]   " if n >= 8 else "  [TODO] ") + "app/pipeline.py live progress/finding calls: %d (want 8+; see LIVE_SCAN_UPGRADE.md Prompt L1)" % n)
    print("\nNext: python -m pytest -q   then follow LIVE_SCAN_UPGRADE.md")
    return 0


if __name__ == "__main__":
    sys.exit(main())
